WITH base AS (SELECT *, DATEDIFF(CURRENT_DATE(), signup_date) days_since_signup_date FROM customers WHERE NOT (YEAR(signup_date) = 2025 AND (is_active OR credit_limit <= 9300))), customers_stats AS (SELECT MONTH(signup_date) signup_month, MIN(days_since_signup_date) min_days_since_signup_date FROM base GROUP BY MONTH(signup_date)) SELECT signup_month, min_days_since_signup_date FROM customers_stats ORDER BY signup_month, min_days_since_signup_date DESC;
